```python
import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    edges = []
    for _ in range(n - 1):
        u = int(next(it)); v = int(next(it)); w = int(next(it))
        edges.append((u, v, w))

    ans = 0
    NEG = -10**18

    for b in range(30):
        forced1 = [False] * (n + 1)
        forced0 = [False] * (n + 1)
        zeroAdj = [[] for _ in range(n + 1)]

        # 构建“0-边”邻接表并标记强制1
        for (u, v, w) in edges:
            if (w >> b) & 1:
                forced1[u] = True
                forced1[v] = True
            else:
                zeroAdj[u].append(v)
                zeroAdj[v].append(u)

        # 强制0：通过“0-边”与强制1相邻的点必须取0
        for u in range(1, n + 1):
            if forced1[u]:
                for v in zeroAdj[u]:
                    forced0[v] = True

        countForced1 = sum(1 for u in range(1, n + 1) if forced1[u])

        # 在“0-边”森林上做树形DP（迭代）
        vis = [False] * (n + 1)
        dp0 = [0] * (n + 1)
        dp1 = [0] * (n + 1)
        addFree = 0

        for s in range(1, n + 1):
            if forced1[s] or vis[s]:
                continue

            # 栈元素：(u, parent, state)；state=0入栈、1出栈
            stack = [(s, 0, 0)]
            vis[s] = True

            while stack:
                u, p, stt = stack.pop()
                if stt == 0:
                    stack.append((u, p, 1))
                    for v in zeroAdj[u]:
                        if v == p or forced1[v] or vis[v]:
                            continue
                        vis[v] = True
                        stack.append((v, u, 0))
                else:
                    take0 = 0
                    take1 = 1 if not forced0[u] else NEG
                    for v in zeroAdj[u]:
                        if v == p or forced1[v]:
                            continue
                        c0, c1 = dp0[v], dp1[v]
                        take0 += c0 if c0 >= c1 else c1
                        if take1 > NEG // 2:
                            take1 += c0
                    dp0[u] = take0
                    dp1[u] = take1
                    if p == 0:
                        addFree += dp0[u] if dp0[u] >= dp1[u] else dp1[u]

        ones = countForced1 + addFree
        ans += ones * (1 << b)

    print(ans)

if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.*;
import java.util.*;

class FastScanner {
    BufferedInputStream in;
    byte[] buffer = new byte[1 << 16];
    int ptr = 0, len = 0;
    FastScanner(InputStream is) { in = new BufferedInputStream(is); }
    int read() throws IOException {
        if (ptr >= len) {
            len = in.read(buffer);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buffer[ptr++];
    }
    int nextInt() throws IOException {
        int c, s = 1, x = 0;
        do { c = read(); } while (c <= 32);
        if (c == '-') { s = -1; c = read(); }
        while (c > 32) { x = x * 10 + (c - '0'); c = read(); }
        return x * s;
    }
}

public class Main {
    static class Edge {
        int u, v, w;
        Edge(int u, int v, int w) { this.u = u; this.v = v; this.w = w; }
    }
    static class Item {
        int u, p, st;
        Item(int u, int p, int st) { this.u = u; this.p = p; this.st = st; }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        ArrayList<Edge> edges = new ArrayList<>(Math.max(1, n - 1));
        for (int i = 0; i < n - 1; ++i) {
            int u = fs.nextInt(), v = fs.nextInt(), w = fs.nextInt();
            edges.add(new Edge(u, v, w));
        }

        long ans = 0L;
        final long NEG = (long)-4e18;

        // 对每一位独立处理
        for (int b = 0; b < 30; ++b) {
            boolean[] forced1 = new boolean[n + 1];
            boolean[] forced0 = new boolean[n + 1];
            @SuppressWarnings("unchecked")
            ArrayList<Integer>[] zeroAdj = new ArrayList[n + 1];
            for (int i = 1; i <= n; ++i) zeroAdj[i] = new ArrayList<>();

            // 标记强制1，并建立“0-边”邻接
            for (Edge e : edges) {
                if (((e.w >> b) & 1) == 1) {
                    forced1[e.u] = true;
                    forced1[e.v] = true;
                } else {
                    zeroAdj[e.u].add(e.v);
                    zeroAdj[e.v].add(e.u);
                }
            }

            // 强制0
            for (int u = 1; u <= n; ++u) if (forced1[u]) {
                for (int v : zeroAdj[u]) forced0[v] = true;
            }

            long countForced1 = 0;
            for (int u = 1; u <= n; ++u) if (forced1[u]) ++countForced1;

            // 在“0-边”森林上做树形DP
            boolean[] vis = new boolean[n + 1];
            long[] dp0 = new long[n + 1];
            long[] dp1 = new long[n + 1];
            long addFree = 0;

            ArrayDeque<Item> st = new ArrayDeque<>();

            for (int s = 1; s <= n; ++s) {
                if (forced1[s] || vis[s]) continue;

                st.clear();
                st.push(new Item(s, 0, 0));
                vis[s] = true;

                while (!st.isEmpty()) {
                    Item cur = st.pop();
                    int u = cur.u, p = cur.p, state = cur.st;

                    if (state == 0) {
                        st.push(new Item(u, p, 1));
                        for (int v : zeroAdj[u]) {
                            if (v == p || forced1[v] || vis[v]) continue;
                            vis[v] = true;
                            st.push(new Item(v, u, 0));
                        }
                    } else {
                        long take0 = 0;
                        long take1 = forced0[u] ? NEG : 1;
                        for (int v : zeroAdj[u]) {
                            if (v == p || forced1[v]) continue;
                            long c0 = dp0[v], c1 = dp1[v];
                            take0 += Math.max(c0, c1);
                            if (take1 > NEG / 2) take1 += c0;
                        }
                        dp0[u] = take0;
                        dp1[u] = take1;
                        if (p == 0) {
                            addFree += Math.max(dp0[u], dp1[u]);
                        }
                    }
                }
            }

            long ones = countForced1 + addFree;
            ans += ones * (1L << b);
        }

        System.out.println(ans);
    }
}
